    git: {getBlob: ({owner, repo, file_sha: sha}) => get(`repos/${owner}/${repo}/git/blobs/${sha}`)}}};
}

// `pull` is what GitHub reports: number, author login, body, head sha and base sha. `base` is the fetched remote base ref
// whose protected configuration governs the receipt. Without a `local_review` section there is no receipt to judge.
async function receiptStanding({directory, base, repo, pull, execute, installed}) {
  if (!git(directory, ['ls-tree', base, '--', '.github/clouseau.json']).trim()) return {applicable: false};
  const config = require('./config.cjs').validateConfig(JSON.parse(git(directory, ['show', `${base}:.github/clouseau.json`])));
  if (!config.local_review) return {applicable: false};
  const reviewer = installed();
  const screened = await screenReceipt({github: githubReader(execute), repo, engine: {...SOURCE, sha: reviewer.sha, digest: reviewer.digest},
    pr: {number: pull.number, body: pull.body, user: {login: pull.author}, head: {sha: pull.head}, base: {sha: pull.base_sha}},
    trust: config.local_review, configDigest: digest(config), policyDigest: digest(fs.readFileSync(POLICY, 'utf8')), reviewerDigest: reviewer.digest});
  // Under the protected `binding: "diff"` the head no longer binds the receipt, so its diff must equal the pull request's, as
  // CI checks it (screenSources), on the changed files GitHub reports now.
  if (screened.ref && config.local_review.binding === 'diff') {
    const files = [];
    for (let page = 1; ; page++) {
      const batch = JSON.parse(execute('gh', ['api', `repos/${repo.owner}/${repo.repo}/pulls/${pull.number}/files?per_page=100&page=${page}`], {encoding: 'utf8', maxBuffer: RECEIPT_RESPONSE_LIMIT}));
      files.push(...batch);
      if (batch.length < 100) break;
    }
    const rejected = await screenSources({github: githubReader(execute), repo, snapshot: screened.verified.record.snapshot, config, files,
      reviewerSha: screened.bundle.payload.reviewer_sha, pr: {number: pull.number, changed_files: pull.changed_files,
        head: {sha: pull.head, repo: {owner: {login: repo.owner}, name: repo.repo}}, base: {sha: pull.base_sha}}});
    if (rejected) {
      const cause = describe(rejected, {});
      return {applicable: true, usable: false, cause: cause.code, sentence: cause.sentence};
    }
    return {applicable: true, usable: true, binding: 'diff'};
  }
  if (screened.ref) return {applicable: true, usable: true};
  const cause = describe(screened.rejected ?? 'absent', {detail: screened.detail});
  return {applicable: true, usable: false, cause: cause.code, sentence: cause.sentence};
}

module.exports = {receiptStanding, githubReader, RECEIPT_RESPONSE_LIMIT};

// The record with one graded blocking finding in the examiner's report and every gate still satisfied: its recalculated
// decision is `repair_required` because of the finding alone. `mutate` runs on the copy before the decision is recomputed.
function withFinding(record, mutate = () => {}) {
  const {FACTORS} = require('../src/acceptance.cjs');
  const {reviewDecision} = require('../src/local-receipt.cjs');
  const copy = structuredClone(record);
  const report = copy.result.reviews[0].report;
  const [evidence] = report.accounting[0].evidence;
  report.findings.push({id: 'fictional-defect', title: 'Fictional defect', path: report.accounting[0].path,
    cause: 'The changed path no longer preserves the accepted contract.', trigger: 'A fictional input.', consequence: 'A fictional regression.',
    obligation: 'Restore the accepted contract.', evidence: [evidence],
    factors: Object.fromEntries(FACTORS.defect.map(name => [name, {value: name.includes('excess') ? 0 : 1, evidence: [evidence], reason: 'Established by the cited source.'}])),
    blast_radius: 1, opportunity: {mechanical: false, beneficial: false, within_scope: false, verified: false}, repair_paths: [report.accounting[0].path]});
  // A role with findings records its grading round as well.
  copy.result.usage = ['examiner', 'challenger'].flatMap(role => ['investigation', 'grading'].map(phase =>
    ({role, phase, harness: 'codex', session: `fictional-${role}-${phase}`, request_digest: digest(role), response_digest: digest(phase), transport_digest: digest({fixture_only: true})})));
  copy.result.execution_digest = digest(copy.result.usage);
  mutate(copy);
  for (const decision of ['repair_required', 'blocked_integrity', 'review_incomplete']) {
    copy.result.decision = decision;
    try {reviewDecision(copy); return copy;} catch { /* try the next decision */ }
  }
  throw new Error('no consistent decision');
}
module.exports = {fixture, withFinding};

